function formatDate(iso) { return new Date(iso + "T00:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" }); }
function initials(name) { return name.split(" ").map((n) => n[0]).join("").slice(0, 2).toUpperCase(); }
function getPostImage(post, index = 0) { return post.images?.[index] || post.images?.[0] || "Assets/20.jpg"; }
function getBlockImage(block) { return block.url || block.src || "Assets/20.jpg"; }

document.addEventListener("DOMContentLoaded", () => {
  gsap.registerPlugin(ScrollTrigger, ScrollSmoother);
  const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;

  ScrollSmoother.create({
    wrapper: "#smooth-wrapper",
    content: "#smooth-content",
    smooth: reduceMotion ? 0 : 1.1,
    effects: true,
    normalizeScroll: true,
  });

  const slug = new URLSearchParams(window.location.search).get("slug");
  const post = POSTS[slug];

  if (!post) {
    document.getElementById("notFound").classList.remove("hidden");
    renderMoreArticles(null);
    document.getElementById("moreArticlesSection").classList.remove("hidden");
    return;
  }

  renderPost(slug, post);
  document.getElementById("postMain").classList.remove("hidden");
  renderMoreArticles(slug);
  document.getElementById("moreArticlesSection").classList.remove("hidden");

  requestAnimationFrame(() => {
    ScrollTrigger.refresh();
    runAnimations(reduceMotion);
  });

  // ---------------- render ----------------

  function renderPost(postSlug, p) {
    document.title = `${p.title} — Viral Ads Media Journal`;
    const authorInfo = AUTHORS[p.author] || { role: "", bio: "" };

    document.getElementById("postCategory").textContent = p.category;
    document.getElementById("postReadTime").textContent = p.readTime;
    document.getElementById("postTitle").textContent = p.title;
    document.getElementById("postDeck").textContent = p.deck;

    if (p.relatedProject) {
      const link = document.getElementById("relatedProjectLink");
      link.href = `project.html?id=${p.relatedProject}`;
      link.classList.remove("hidden");
    }

    document.getElementById("authorAvatar").textContent = initials(p.author);
    document.getElementById("authorNameLine").textContent = `${p.author} — ${authorInfo.role}`;
    document.getElementById("postDateLine").textContent = `${formatDate(p.date)} · ${p.readTime}`;

    document.getElementById("heroImage").src = getPostImage(p);
    document.getElementById("heroImage").alt = p.title;

    const body = document.getElementById("articleBody");
    p.body.forEach((block) => {
      const el = document.createElement("div");
      el.className = "body-block";
      if (block.type === "p") {
        el.innerHTML = `<p class="text-bone/85 leading-relaxed text-base lg:text-lg">${block.text}</p>`;
      } else if (block.type === "h2") {
        el.innerHTML = `<h2 class="font-display text-2xl lg:text-3xl tracking-wide pt-2">${block.text}</h2>`;
      } else if (block.type === "quote") {
        el.innerHTML = `<blockquote class="border-l-2 border-accent pl-5 py-1"><p class="font-display text-xl lg:text-2xl leading-snug text-bone">${block.text}</p></blockquote>`;
      } else if (block.type === "image") {
        el.innerHTML = `
          <figure class="media-card relative overflow-hidden rounded-sm bg-surface h-[34vh] lg:h-[44vh] -mx-6 lg:mx-0">
            <img class="media-img" src="${getBlockImage(block)}" alt="${block.caption || ""}" loading="lazy" decoding="async">
          </figure>
          ${block.caption ? `<figcaption class="font-mono text-[10px] uppercase tracking-widest text-smoke mt-2">${block.caption}</figcaption>` : ""}`;
      }
      body.appendChild(el);
    });

    const tagsRow = document.getElementById("tagsRow");
    p.tags.forEach((t) => {
      const span = document.createElement("span");
      span.className = "chip border border-line text-smoke";
      span.textContent = t;
      tagsRow.appendChild(span);
    });

    // Author card, with any other posts by the same author surfaced
    const otherByAuthor = Object.entries(POSTS).filter(([s, post2]) => post2.author === p.author && s !== postSlug);
    document.getElementById("authorCard").innerHTML = `
      <span class="w-14 h-14 rounded-full bg-line flex items-center justify-center font-mono text-sm shrink-0">${initials(p.author)}</span>
      <div>
        <p class="font-display text-2xl tracking-wide">${p.author}</p>
        <p class="font-mono text-[10px] uppercase tracking-widest text-accent mt-1">${authorInfo.role}</p>
        <p class="text-smoke mt-3 leading-relaxed">${authorInfo.bio}</p>
        ${otherByAuthor.length ? `<p class="font-mono text-[10px] uppercase tracking-widest text-smoke mt-4">Also by ${p.author}: ${otherByAuthor.map(([s, post2]) => `<a href="blog-post.html?slug=${s}" class="text-bone hover:text-accent transition-colors underline underline-offset-2">${post2.title}</a>`).join(", ")}</p>` : ""}
      </div>`;

    // Copy-link button
    document.getElementById("copyLinkBtn").addEventListener("click", async () => {
      try {
        await navigator.clipboard.writeText(window.location.href);
      } catch (e) {
        /* clipboard API unavailable — fail silently, link is still visible in the address bar */
      }
      document.getElementById("copyLinkConfirm").classList.remove("hidden");
      setTimeout(() => document.getElementById("copyLinkConfirm").classList.add("hidden"), 2000);
    });

    const idx = POST_ORDER.indexOf(postSlug);
    const nextSlug = POST_ORDER[(idx + 1) % POST_ORDER.length];
    const nextPost = POSTS[nextSlug];
    document.getElementById("nextArticleLink").href = `blog-post.html?slug=${nextSlug}`;
    document.getElementById("nextArticleTitle").textContent = nextPost.title;
  }

  function renderMoreArticles(currentSlug) {
    const grid = document.getElementById("moreArticlesGrid");
    const startIdx = currentSlug ? (POST_ORDER.indexOf(currentSlug) + 1) % POST_ORDER.length : 0;
    const others = [];
    for (let i = 0; i < POST_ORDER.length && others.length < 3; i++) {
      const candidate = POST_ORDER[(startIdx + i) % POST_ORDER.length];
      if (candidate !== currentSlug) others.push(candidate);
    }

    others.forEach((s) => {
      const p = POSTS[s];
      const card = document.createElement("a");
      card.href = `blog-post.html?slug=${s}`;
      card.className = "media-card group block more-article-item";
      card.setAttribute("aria-label", `Read ${p.title}`);
      card.innerHTML = `
        <div class="relative overflow-hidden rounded-sm bg-surface h-[32vh] lg:h-[36vh]">
          <img class="media-img" src="${getPostImage(p)}" alt="" loading="lazy" decoding="async">
          <span class="chip absolute top-4 left-4 bg-ink/80 text-bone border border-line">${p.category}</span>
        </div>
        <h3 class="font-display text-xl lg:text-2xl tracking-wide mt-4 leading-tight group-hover:text-accent transition-colors">${p.title}</h3>
        <p class="font-mono text-[10px] text-smoke uppercase tracking-widest mt-3">${p.author} · ${formatDate(p.date)} · ${p.readTime}</p>`;
      grid.appendChild(card);
    });
  }

  function runAnimations(reduce) {
    // Reading-progress rail, tied to the article's own scroll length
    ScrollTrigger.create({
      trigger: "#postMain",
      start: "top top",
      end: "bottom bottom",
      onUpdate: (self) => {
        document.getElementById("readingProgress").style.width = self.progress * 100 + "%";
      },
    });

    if (reduce) {
      gsap.set([".header-block", ".body-block", ".more-article-item"], { opacity: 1, y: 0 });
      return;
    }

    gsap.set(".header-block", { opacity: 0, y: 20 });
    gsap.timeline().to(".header-block", { opacity: 1, y: 0, duration: 0.8, ease: "power3.out", stagger: 0.1 });

    gsap.utils.toArray(".body-block").forEach((el) => {
      gsap.from(el, {
        opacity: 0, y: 24, duration: 0.7, ease: "power3.out",
        scrollTrigger: { trigger: el, start: "top 90%", toggleActions: "play none none reverse" },
      });
    });

    gsap.utils.toArray(".more-article-item").forEach((el, i) => {
      gsap.from(el, {
        opacity: 0, y: 40, duration: 0.8, ease: "power3.out",
        scrollTrigger: { trigger: el, start: "top 90%", toggleActions: "play none none reverse" },
        delay: i * 0.08,
      });
    });
  }
})
